CREATE DATABASE IF NOT EXISTS verbrauch;
USE verbrauch;

CREATE TABLE IF NOT EXISTS arotherm_plus_data (
                                                  id INT AUTO_INCREMENT PRIMARY KEY,
                                                  date_time DATETIME,
                                                  consumed_electrical_energy_heating DOUBLE,
                                                  consumed_electrical_energy_domestic_hot_water DOUBLE,
                                                  heat_generated_heating DOUBLE,
                                                  heat_generated_domestic_hot_water DOUBLE,
                                                  earned_environment_energy_heating DOUBLE,
                                                  earned_environment_energy_domestic_hot_water DOUBLE
);



